cenozoApp.defineModule({name:"participant_data",models:["add","list","view"],create:module=>{angular.extend(module,{identifier:{parent:{subject:"study_phase",column:"study_phase.id"}},name:{singular:"participant data",plural:"participant data",possessive:"participant data's"},columnList:{formatted_study_phase_id:{title:"Study & Phase Name",isIncluded:function($state,model){return"study_phase"!=model.getSubjectFromState()}},category:{title:"Category"},name:{title:"Name"}},defaultOrder:{column:"study_phase.rank",reverse:false}});module.addInputGroup("",{study_phase_id:{title:"Full Study Name",type:"lookup-typeahead",typeahead:{table:"study_phase",select:'CONCAT( study.name, ": ", study_phase.name )',where:["study.name","study_phase.name"]},isConstant:true},category:{title:"Category",type:"string",format:"identifier"},name:{title:"Name",type:"string",format:"identifier"},filetype:{title:"File Type",type:"string",help:"The type of file (as a file extension) this data provides."},path:{title:"Path",type:"string",help:"For supplemental data only: the path to the data file (where <UID> should be used in place of the participant's unique identifier."}});cenozo.providers.factory("CnParticipantDataViewFactory",["CnBaseViewFactory",function(CnBaseViewFactory){var object=function(parentModel,root){CnBaseViewFactory.construct(this,parentModel,root,"cohort");async function init(object){await object.deferred.promise;if(angular.isDefined(object.cohortModel)){object.cohortModel.getChooseEnabled=function(){return parentModel.getEditEnabled()}}}init(this)};return{instance:function(parentModel,root){return new object(parentModel,root)}}}])}});
